WITH by_dimension AS (SELECT p.brand, p.category, COUNT(*) AS cnt, MAX(src.quantity) AS max_quantity, MIN(src.unit_price) AS min_unit_price, GROUPING_ID() AS grouping_level FROM order_items src LEFT JOIN products p ON src.product_id = p.id GROUP BY GROUPING SETS ((p.brand, p.category), (p.brand), ())) SELECT brand, category, max_quantity, grouping_level, CASE WHEN brand RLIKE '^(Umbrella|Globex)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS brand_zone FROM by_dimension ORDER BY max_quantity DESC, brand
